"

cd /tmp; node -e "
const d=JSON.parse(require('fs').readFileSync('/tmp/gbrain-setup.json','utf8'));
console.log('state',d.state);console.log('verify',JSON.stringify(d.verify).slice(0,800));
for(const s of d.steps||[])console.log(JSON.stringify(s));
console.log('instructions',JSON.stringify(d.instructions));
for(const n of d.notices||[]){console.log('NOTICE',n.code,n.kind);console.log(n.user_message);for(const x of n.decisions||[])console.log(' -',x.id,'default:',x.default)}
"; cat /harness-state/claude/settings.json; echo; cat /harness-state/claude/CLAUDE.md

