input.command:
mkdir -p /tmp/gbrain-scripts && cat > /tmp/gbrain-scripts/mcp-check.mjs <<'EOF'
import { spawn } from 'node:child_process';
const [cmd, ...args] = process.argv.slice(2);
const p = spawn(cmd, args, { stdio: ['pipe', 'pipe', 'inherit'] });
let buf = '', id = 0; const waiters = {};
p.stdout.on('data', d => { buf += d; let i; while ((i = buf.indexOf('\n')) >= 0) { const line = buf.slice(0, i); buf = buf.slice(i + 1); try { const m = JSON.parse(line); if (m.id != null && waiters[m.id]) waiters[m.id](m); } catch {} } });
const rpc = (method, params) => new Promise(r => { const n = ++id; waiters[n] = r; p.stdin.write(JSON.stringify({ jsonrpc: '2.0', id: n, method, params }) + '\n'); });
const init = await rpc('initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'install-check', version: '1' } });
console.log('server:', JSON.stringify(init.result?.serverInfo));
p.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' }) + '\n');
const tools = await rpc('tools/list', {});
console.log('tools:', tools.result.tools.map(t => t.name).join(', '));
const r = await rpc('tools/call', { name: 'recall', arguments: { query: 'install-check marker', entity: 'install-check' } });
console.log('recall:', JSON.stringify(r.result ?? r.error).slice(0, 1500));
p.kill(); process.exit(0);
EOF
export PATH="$HOME/.bun/bin:$PATH"; cd /tmp; timeout 90 node /tmp/gbrain-scripts/mcp-check.mjs /harness-state/.gbrain/hook-launcher/gbrain-hook /harness-state/.bun/bin/gbrain serve --surface starter --advertise verbs 2>&1 | tail -8
